// Pure mapping: resin bars / plot value series / candle channels → LWC data arrays.
/**
 * Bar times as LWC `Time` (UTC seconds). resin carries milliseconds; when the
 * data has no `time`, synthesize a daily sequence so the chart still lays out —
 * the same fallback resin's own CLI uses for `--bars`.
 */
export function barTimes(bars, barCount) {
    const times = [];
    const start = Date.UTC(2020, 0, 1);
    for (let i = 0; i < barCount; i++) {
        const ms = bars.time?.[i] ?? start + i * 86_400_000;
        times.push(Math.floor(ms / 1000));
    }
    return times;
}
function finite(v) {
    return typeof v === "number" && Number.isFinite(v) ? v : null;
}
/** Plot values → line/area/histogram points; na becomes whitespace (a gap). */
export function valuePoints(values, times, colors) {
    const out = [];
    for (let i = 0; i < times.length; i++) {
        const time = times[i];
        const v = finite(values[i]);
        if (v === null) {
            out.push({ time });
            continue;
        }
        const color = colors?.[i];
        out.push(color != null ? { time, value: v, color } : { time, value: v });
    }
    return out;
}
/** The main pane's candlesticks from raw OHLCV, with barcolor overrides applied. */
export function mainCandles(bars, times, barcolors) {
    const out = [];
    for (let i = 0; i < times.length; i++) {
        const time = times[i];
        const open = finite(bars.open[i]);
        const high = finite(bars.high[i]);
        const low = finite(bars.low[i]);
        const close = finite(bars.close[i]);
        if (open === null || high === null || low === null || close === null) {
            out.push({ time });
            continue;
        }
        // Last barcolor() call wins per bar, matching TV's paint order.
        let override = null;
        for (const bc of barcolors) {
            const c = bc.colors?.[i] ?? bc.color;
            if (c != null)
                override = c;
        }
        out.push(override !== null
            ? { time, open, high, low, close, color: override, wickColor: override, borderColor: override }
            : { time, open, high, low, close });
    }
    return out;
}
/** plotcandle / plotbar channels → candlestick points with per-bar colors. */
export function candlePoints(candle, times) {
    const out = [];
    for (let i = 0; i < times.length; i++) {
        const time = times[i];
        const open = finite(candle.open[i]);
        const high = finite(candle.high[i]);
        const low = finite(candle.low[i]);
        const close = finite(candle.close[i]);
        if (open === null || high === null || low === null || close === null) {
            out.push({ time });
            continue;
        }
        const color = candle.colors?.[i] ?? candle.color;
        out.push({
            time,
            open,
            high,
            low,
            close,
            ...(color != null ? { color } : {}),
            ...(candle.wickcolor !== null ? { wickColor: candle.wickcolor } : {}),
            ...(candle.bordercolor !== null ? { borderColor: candle.bordercolor } : {}),
        });
    }
    return out;
}
/** First non-null color a series will fall back to when LWC needs one base color. */
export function baseColor(color, colors, dflt) {
    if (color !== null)
        return color;
    if (colors !== null) {
        for (const c of colors)
            if (c !== null)
                return c;
    }
    return dflt;
}
